export declare const cssText = "\n.dshPluginAudit_root {\n  display: flex;\n  flex-direction: column;\n  gap: 14px;\n  width: 100%;\n  max-width: 760px;\n  color: var(--dsw-alias-label-primary);\n}\n.dshPluginAudit_search input {\n  box-sizing: border-box;\n  width: 100%;\n  height: 36px;\n  padding: 0 12px;\n  border: 1px solid var(--dsw-alias-border-l2);\n  border-radius: 8px;\n  background: var(--dsw-alias-bg-layer-1);\n  color: var(--dsw-alias-label-primary);\n  font: inherit;\n  font-size: 13px;\n  outline: none;\n}\n.dshPluginAudit_search input:focus-visible {\n  border-color: var(--dsw-alias-state-business-primary);\n}\n.dshPluginAudit_section {\n  display: flex;\n  flex-direction: column;\n  gap: 8px;\n}\n.dshPluginAudit_heading {\n  display: flex;\n  align-items: baseline;\n  gap: 7px;\n  margin: 0;\n  padding: 0 2px;\n  font-size: 13px;\n  font-weight: 600;\n  line-height: 20px;\n}\n.dshPluginAudit_heading span {\n  color: var(--dsw-alias-label-tertiary);\n  font-size: 12px;\n  font-variant-numeric: tabular-nums;\n}\n.dshPluginAudit_cards {\n  display: grid;\n  grid-template-columns: repeat(2, minmax(0, 1fr));\n  gap: 10px;\n  margin: 0;\n  padding: 0;\n  list-style: none;\n}\n.dshPluginAudit_card {\n  display: flex;\n  flex-direction: column;\n  gap: 6px;\n  min-width: 0;\n  padding: 10px 12px;\n  border: 1px solid var(--dsw-alias-border-l2);\n  border-radius: 10px;\n  background: var(--dsw-alias-bg-layer-3);\n}\n.dshPluginAudit_cardTitle {\n  min-width: 0;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n  font-size: 14px;\n  font-weight: 600;\n  line-height: 20px;\n}\n.dshPluginAudit_cardMeta {\n  display: flex;\n  align-items: center;\n  gap: 6px;\n  flex-wrap: wrap;\n}\n.dshPluginAudit_badge {\n  padding: 1px 6px;\n  border-radius: 5px;\n  background: var(--dsw-alias-bg-layer-1);\n  color: var(--dsw-alias-label-secondary);\n  font-size: 11px;\n  line-height: 16px;\n  white-space: nowrap;\n}\n.dshPluginAudit_badge[data-enabled='true'] {\n  background: color-mix(in srgb, var(--dsw-alias-state-success-primary) 10%, transparent);\n  color: var(--dsw-alias-state-success-primary);\n}\n.dshPluginAudit_badge[data-origin='user'] {\n  background: color-mix(in srgb, var(--dsw-alias-state-business-primary) 10%, transparent);\n  color: var(--dsw-alias-state-business-primary);\n}\n.dshPluginAudit_entry {\n  min-width: 0;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n  color: var(--dsw-alias-label-tertiary);\n  font-family: var(--ds-font-family-code);\n  font-size: 11px;\n  line-height: 16px;\n}\n.dshPluginAudit_toggle {\n  padding: 2px 10px;\n  border: 1px solid var(--dsw-alias-border-l2);\n  border-radius: 6px;\n  background: var(--dsw-alias-bg-layer-1);\n  color: var(--dsw-alias-label-secondary);\n  font: inherit;\n  font-size: 12px;\n  line-height: 18px;\n  cursor: pointer;\n}\n.dshPluginAudit_toggle:hover:not(:disabled) {\n  background: var(--dsw-alias-interactive-bg-hover);\n}\n.dshPluginAudit_toggle:disabled {\n  opacity: 0.6;\n  cursor: default;\n}\n.dshPluginAudit_toggle[data-enabled='true'] {\n  color: var(--dsw-alias-state-error-primary);\n}\n.dshPluginAudit_toggle[data-enabled='false'] {\n  color: var(--dsw-alias-state-success-primary);\n}\n.dshPluginAudit_toggleError {\n  margin: 0;\n  color: var(--dsw-alias-state-error-primary);\n  font-size: 12px;\n  line-height: 18px;\n}\n.dshPluginAudit_status,\n.dshPluginAudit_failure {\n  color: var(--dsw-alias-label-tertiary);\n  font-size: 13px;\n  line-height: 20px;\n}\n.dshPluginAudit_failure {\n  display: flex;\n  align-items: center;\n  gap: 10px;\n  color: var(--dsw-alias-state-error-primary);\n}\n.dshPluginAudit_failure button {\n  padding: 4px 10px;\n  border: 1px solid var(--dsw-alias-border-l2);\n  border-radius: 6px;\n  background: none;\n  color: var(--dsw-alias-label-primary);\n  font: inherit;\n  cursor: pointer;\n}\n@media (max-width: 680px) {\n  .dshPluginAudit_cards {\n    grid-template-columns: minmax(0, 1fr);\n  }\n}\n";
